'use strict';
(()=>{
 function publish(){try{if(!window.WidgetBridge||!state)return;const faults=[],seen=new Set(),meta=state.faultSyncMeta||{};for(const a of state.assets||[])for(const f of a.faults||[]){const m=meta[f.id]||{};seen.add(f.id);faults.push({id:f.id,status:f.status,asset:a.name,at:Number(m.at)||Date.parse(f.updatedAt)||0,eventId:m.eventId||'',deleted:!!m.deleted});}for(const [id,m] of Object.entries(meta))if(m.deleted&&!seen.has(id))faults.push({id,status:'',asset:'',at:Number(m.at)||0,eventId:m.eventId||'',deleted:true});const todayCount=window.getTodayOpenCount?window.getTodayOpenCount():0;WidgetBridge.update(JSON.stringify({faults,todayCount}));}catch(e){console.warn('Widget konnte nicht aktualisiert werden',e);}}
 const save=persist;persist=function(next){const ok=save(next);if(ok)publish();return ok;};
 publish();
 const button=document.createElement('button');button.id='openWidgetSetup';button.className='light';button.textContent='Startbildschirm-Widget';document.querySelector('footer .actions').appendChild(button);
 button.onclick=()=>{modal('<h2>Startbildschirm-Widget</h2><p>Busch-Logo, Störungen, Bearbeitung und Tagesgeschäft auf dem Startbildschirm.</p><p>Nach dem Update die App einmal öffnen. Danach aktualisiert der Hintergrundabgleich das Widget automatisch. „Aktualisieren“ öffnet die App zum Abgleich.</p><div class="actions"><button id="pinWidget">Widget hinzufügen</button><button id="cancel" class="light">Schließen</button></div><p class="hint">Alternativ: Eine freie Stelle auf dem Samsung-Startbildschirm lange drücken → Widgets → Anlagenbuch → hinzufügen. Der Hintergrundabgleich läuft normalerweise etwa alle 15 Minuten und kann durch Energiesparen verzögert werden. Dies ist ein Startbildschirm-Widget, kein neuer Sofort-Push-Dienst.</p>');document.getElementById('pinWidget').onclick=()=>{try{if(window.WidgetBridge&&WidgetBridge.pin())toast('Bitte das Hinzufügen auf dem Startbildschirm bestätigen.');else toast('Bitte über langes Drücken auf den Startbildschirm → Widgets → Anlagenbuch hinzufügen.');}catch(e){toast('Bitte das Widget über den Startbildschirm hinzufügen.');}};};
})();
                                                                             